query:
-- Count ghost users first to confirm scope
SELECT COUNT(*) as ghost_count 
FROM users 
WHERE email IS NULL AND openId IS NULL;

-- Delete ghost users with no email AND no openId (truly empty rows from failed OAuth)
DELETE FROM users 
WHERE email IS NULL AND openId IS NULL;

-- Verify remaining user count
SELECT COUNT(*) as remaining_users FROM users;
SELECT COUNT(*) as users_with_email FROM users WHERE email IS NOT NULL;
SELECT COUNT(*) as users_with_openid FROM users WHERE openId IS NOT NULL;

